  "Adverse yaw": { def: "The nose yawing toward the outside of a turn as you roll in, caused by the extra induced drag on the rising wing. Correct it with coordinated rudder.", src: "PHAK Glossary" },
  // Axes and stability
  "Longitudinal axis": { def: "An imaginary line through the CG from nose to tail. Movement about it is roll.", src: "PHAK Glossary" },
  "Lateral axis": { def: "An imaginary line through the CG from wingtip to wingtip. Movement about it is pitch.", src: "PHAK Glossary" },
  "Vertical axis": { def: "An imaginary line through the CG, perpendicular to the other two axes. Movement about it is yaw.", src: "PHAK Glossary" },
  "Static stability": { def: "The airplane's initial tendency after a disturbance: positive returns toward equilibrium, neutral stays, negative moves further away.", src: "PHAK Ch 5" },
  "Dynamic stability": { def: "How the airplane responds over time after a disturbance: whether its oscillations die out (positive), continue (neutral) or grow (negative).", src: "PHAK Ch 5" },
  // Aerodynamics
  "Lift": { def: "The force from the wing that acts perpendicular to the relative wind. You control it with angle of attack and airspeed.", src: "PHAK Ch 5" },
  "Weight": { def: "The combined load of the airplane, people, fuel and cargo. It acts straight down toward the center of the Earth.", src: "PHAK Ch 5" },
  "Thrust": { def: "The forward force produced by the propeller.", src: "PHAK Ch 5" },
  "Drag": { def: "The force that resists the airplane's motion through the air, acting parallel to the relative wind. It has two kinds: parasite and induced.", src: "PHAK Ch 5" },
  "Parasite drag": { def: "Drag not related to lift: form, interference and skin friction drag. It increases with airspeed.", src: "PHAK Ch 5" },
  "Induced drag": { def: "Drag that is a by-product of producing lift. It is greatest at low airspeed and high angle of attack.", src: "PHAK Ch 5" },
  "L/D max": { def: "The maximum lift-to-drag ratio. Its speed is where total drag is lowest; it gives the best glide.", src: "PHAK Ch 5" },
  "Relative wind": { def: "The airflow meeting the wing, parallel and opposite to the flight path.", src: "PHAK Ch 4, 5" },
  "Chord line": { def: "An imaginary straight line from the leading edge to the trailing edge of an airfoil.", src: "PHAK Glossary" },
  "Angle of attack": { def: "The angle between the wing's chord line and the relative wind.", src: "PHAK Glossary" },
  "Critical angle of attack": { def: "The angle of attack at which the wing stalls, regardless of airspeed, attitude or weight.", src: "PHAK Glossary" },
  "Stall": { def: "The loss of lift when the wing exceeds its critical angle of attack. It can happen at any airspeed, in any attitude, at any power setting.", src: "PHAK Ch 5; AFH Ch 5" },
  "Bernoulli's principle": { def: "As a fluid's speed increases, its pressure decreases. It helps explain the lower pressure over a wing's curved upper surface.", src: "PHAK Ch 4; Glossary" },
  "Load factor": { def: "The ratio of the load on the wings to the airplane's weight, in G. It rises in turns and pull-ups, and stall speed rises with it.", src: "PHAK Ch 5" },
  "Maneuvering speed": { def: "VA, the design maneuvering speed. At or below it the airplane stalls before exceeding its limit load factor, but it does not protect against full control inputs in more than one axis or repeated full inputs.", src: "PHAK Ch 5; Glossary" },
  "Region of reversed command": { def: "Flight slower than the minimum-drag speed, where flying slower takes more power, not less.", src: "PHAK Ch 11" },
  "Precession": { def: "The tilting of a spinning gyro in response to a force. The force acts 90° ahead in the direction of rotation.", src: "PHAK Ch 5, 8; Glossary" },
